import {experiments,simulate} from './model.js';
import {LabScene} from './scene.js';
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current=experiments[0],params={},progress=0,running=false,activeTab='explore',freeMode=false,lab,notes=[],completed=[],history=[],lastFrame=0;
try{notes=JSON.parse(localStorage.getItem('chemia-notes')||'[]');completed=JSON.parse(localStorage.getItem('chemia-completed')||'[]');if(!Array.isArray(notes))notes=[];if(!Array.isArray(completed))completed=[];}catch{notes=[];completed=[];}
function persist(){try{localStorage.setItem('chemia-notes',JSON.stringify(notes));localStorage.setItem('chemia-completed',JSON.stringify(completed));return true;}catch{toast('Browser storage is unavailable. Export your notes to keep them.');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function illustration(e){const colors={titration:'#cc9bb5',gas:'#acbe8a',electrolysis:'#91bdc0',precipitation:'#d8d5b8',heating:'#d4a074',diffusion:'#a995c1'};let c=colors[e.id];let flask='<path d="M58 16h16v23l24 43q3 8-7 8H42q-9 0-5-8l21-43z" fill="#f8faee" fill-opacity=".6" stroke="#79927d" stroke-width="1.5"/><path d="M49 61h35l12 22q2 5-6 5H43q-6 0-3-5z" fill="'+c+'" fill-opacity=".7"/><path d="M62 23v19L44 78" fill="none" stroke="white" stroke-width="3" opacity=".7"/><path d="M55 15h22" stroke="#68846d" stroke-width="2"/><path d="M78 72h8m-12 7h16" stroke="#7e9580"/>';
let beaker='<path d="M39 26h56l-4 8v51q0 5-5 5H46q-5 0-5-5V31z" fill="#f9fbee" fill-opacity=".6" stroke="#79927d" stroke-width="1.5"/><path d="M43 53h46v31q0 4-4 4H47q-4 0-4-4z" fill="'+c+'" fill-opacity=".7"/><path d="M46 36v44" stroke="white" stroke-width="3" opacity=".7"/><path d="M79 41h10m-10 13h10m-10 13h10m-10 13h10" stroke="#79927d"/>';
let extra=e.id==='titration'?'<path d="M28 8v83H18h24M28 20h39M67 3v40" stroke="#718873" fill="none" stroke-width="2"/><path d="M63 3h8v36h-8z" fill="#d4e3cb" stroke="#718873"/><path d="M61 42h12" stroke="#397363" stroke-width="2"/>':e.id==='gas'?'<path d="M67 13V7h42v51" stroke="#8b9b7a" fill="none" stroke-width="3"/><circle cx="74" cy="64" r="3" fill="#f4f8de"/><circle cx="64" cy="77" r="2" fill="#f4f8de"/>':e.id==='electrolysis'?'<path d="M56 8v61m22-61v61" stroke="#65827a" stroke-width="3"/><path d="M53 9h6v44h-6zm22 0h6v25h-6z" fill="#c4ded2" stroke="#6b8b78"/>':e.id==='heating'?'<rect x="34" y="90" width="63" height="9" rx="3" fill="#49725f"/><path d="M71 5v62" stroke="#bd7957" stroke-width="3"/>':e.id==='diffusion'?'<g fill="#785495"><circle cx="57" cy="61" r="2"/><circle cx="69" cy="70" r="2"/><circle cx="78" cy="58" r="2"/><circle cx="62" cy="79" r="2"/><circle cx="82" cy="80" r="2"/></g>':'<path d="M48 81l4-3 4 4 5-3 4 3 4-2 6 3 4-3 5 2" stroke="#fdfcf2" stroke-width="4"/>';
return '<svg viewBox="0 0 134 108" aria-hidden="true"><ellipse cx="68" cy="96" rx="38" ry="5" fill="#344f3810"/>'+(['titration','gas'].includes(e.id)?flask:beaker)+extra+'</svg>';}
function card(e){return `<button class="lesson-card ${e.id===current.id?'selected':''}" data-experiment="${e.id}" aria-label="Open ${e.name}"><div class="card-art" style="background:${e.color}22"><span class="card-number">${e.tag}</span>${illustration(e)}<span class="card-check">${completed.includes(e.id)?'✓':e.id===current.id?'↗':''}</span></div><div class="card-body"><h3>${e.name}</h3><p>${e.category}<span>${e.time}</span></p></div></button>`;}
function cards(){ $('#lesson-cards').innerHTML=experiments.map(card).join('');$('#progress-label').textContent=`${completed.length} / 6 explored`;$('#note-count').textContent=notes.length||'';}
function select(id){current=experiments.find(e=>e.id===id)||experiments[0];params=Object.fromEntries(current.controls.map(c=>[c.id,c.value]));progress=0;running=false;history=[];activeTab='explore';$('#experiment-title').innerHTML=(freeMode?'Your own discovery':current.title)+'<span>.</span>';$('#experiment-subtitle').textContent=freeMode?'Choose a reaction model, add apparatus, and explore the variables.':current.subtitle;$('#category').textContent=current.category.toUpperCase();$('#scene-number').textContent='EXPERIMENT '+current.tag+' / 06';$('#scene-topic').textContent=current.name.toUpperCase();$('#scene-caption').textContent=current.caption;$('#object-info').hidden=true;if(lab)lab.build(current.id);renderPanel();cards();update();if(location.hash!=='#'+current.id)window.history.replaceState(null,'','#'+current.id);}
function renderPanel(){document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===activeTab));const e=current;
 if(activeTab==='explore'){$('#panel-content').innerHTML=`<h2>${e.name}</h2><p class="description">${e.description}</p><div class="equation">${e.equation}</div>${freeMode?`<div class="control"><label for="reaction">Reaction model</label><select id="reaction">${experiments.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${x.name}</option>`).join('')}</select><div class="sandbox-tools"><button id="add-vessel">＋ Add vessel</button><button id="remove-vessel">− Last vessel</button><button id="exit-free">Exit free lab</button></div></div>`:''}${e.controls.map(c=>`<div class="control"><label for="${c.id}">${c.label}<output id="output-${c.id}" for="${c.id}">${params[c.id].toFixed(c.digits)} ${c.unit}</output></label><input type="range" id="${c.id}" min="${c.min}" max="${c.max}" step="${c.step}" value="${params[c.id]}" aria-label="${c.label}"><div class="range-meta"><span>${c.min} ${c.unit}</span><span>${c.max} ${c.unit}</span></div></div>`).join('')}<div class="metrics"><div class="metric"><label>${e.metricA}</label><strong id="metric-a">0</strong><small>${e.unitA}</small></div><div class="metric"><label>${e.metricB}</label><strong id="metric-b">0</strong><small>${e.unitB}</small></div></div><svg id="chart" class="sparkline" viewBox="0 0 270 45" role="img" aria-label="${e.metricA} during this experiment"></svg><p class="hint" id="result-hint"></p>`;
 for(let c of e.controls)$('#'+c.id).addEventListener('input',event=>{params[c.id]=Number(event.target.value);$('#output-'+c.id).textContent=params[c.id].toFixed(c.digits)+' '+c.unit;history=[];update();});
 if(freeMode){$('#reaction').addEventListener('change',e=>select(e.target.value));$('#add-vessel').onclick=()=>toast(lab?.addVessel()?'Vessel added to your workbench.': 'The workbench holds up to four extra vessels.');$('#remove-vessel').onclick=()=>{let g=lab?.extra.pop();if(g){lab.world.remove(g);toast('Last extra vessel removed.')}else toast('There are no extra vessels to remove.');};$('#exit-free').onclick=()=>{freeMode=false;select(current.id);};}
 }else if(activeTab==='guide'){$('#panel-content').innerHTML=`<h2>Look a little closer.</h2><p class="description">A guided investigation into ${e.category.toLowerCase()}.</p><div class="equation">${e.equation}</div><ol class="guide-steps">${e.steps.map(s=>'<li>'+s+'</li>').join('')}</ol><p class="science-note">${e.science}</p>`;}else{$('#panel-content').innerHTML=`<h2>Put it to the test.</h2><p class="description">Run the experiment, then check your understanding.</p><p style="font-size:13px;line-height:1.7">${e.question}</p>${e.answers.map((a,i)=>`<button class="quiz-option" data-answer="${i}">${String.fromCharCode(65+i)}. &nbsp; ${a}</button>`).join('')}<p class="feedback" id="quiz-feedback" aria-live="polite"></p>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.answer)===e.answer;b.classList.add(correct?'correct':'wrong');$('#quiz-feedback').textContent=(correct?'Exactly. ':'Try again. ')+e.explanation;if(correct)complete();});}update();}
function complete(){if(!completed.includes(current.id)){completed.push(current.id);persist();cards();}}
function update(){const result=simulate(current.id,params,progress);if(lab)lab.update(params,progress,result,running);if($('#metric-a')){$('#metric-a').textContent=result.a.toFixed(current.id==='titration'?2:1);$('#metric-b').textContent=result.b.toFixed(1);$('#result-hint').textContent=result.hint;drawChart();}$('#run').innerHTML=running?'<span>Ⅱ</span> Pause experiment':progress>=1?'<span>↻</span> Run again':'<span>▶</span> '+(progress>0?'Resume experiment':'Run experiment');$('#run-status').textContent=running?'Observing · '+Math.round(progress*100)+'%':progress>=1?'Experiment complete':progress>0?'Paused · '+Math.round(progress*100)+'%':'Ready when you are';return result;}
function drawChart(){let points=[];for(let i=0;i<=60;i++){let t=i/60*progress;points.push(simulate(current.id,params,t).a);}let max=current.id==='titration'?14:Math.max(1,...points)*1.15;let min=0;let coords=points.map((v,i)=>`${i/60*265},${42-(v-min)/max*38}`).join(' ');$('#chart').innerHTML=`<path d="M0 42H270" stroke="#e1e7d7"/><polyline points="${coords}" fill="none" stroke="#4d8670" stroke-width="1.8"/><text x="0" y="9" font-size="7" fill="#96a18a">${current.metricA} over time</text>`;}
function loop(ts){requestAnimationFrame(loop);let dt=Math.min(.1,(ts-lastFrame)/1000)||0;lastFrame=ts;if(running){progress=Math.min(1,progress+dt/20);if(progress>=1){running=false;complete();toast('Experiment complete. Record what you discovered.');}update();}}
$('#run').onclick=()=>{if(progress>=1)progress=0;running=!running;update();};$('#reset').onclick=()=>{progress=0;running=false;history=[];update();toast('Experiment reset. Your variable settings are kept.');};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;renderPanel();});
function openDialog(view){const names={library:'Find your next discovery',apparatus:'Tools of the trade',notebook:'Your lab notebook',help:'A laboratory for curious minds'};$('#dialog-title').textContent=names[view]||names.library;$('#dialog-kicker').textContent=view==='notebook'?'OBSERVE · QUESTION · REMEMBER':view==='apparatus'?'GET TO KNOW YOUR APPARATUS':'CHEMIA / THE INTERACTIVE LAB';document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 if(view==='library'){$('#dialog-body').innerHTML=`<div class="library-tools"><input id="search" class="input" type="search" placeholder="Search experiments…" aria-label="Search experiments"><select id="filter" aria-label="Filter experiments"><option value="all">All topics</option>${[...new Set(experiments.map(e=>e.category))].map(c=>`<option>${c}</option>`).join('')}</select></div><div id="filtered-cards" class="dialog-cards"></div><p class="science-note">Six interactive experiments available in this first release. Each includes adjustable variables, a scientific model, and a knowledge check.</p>`;let filter=()=>{let q=$('#search').value.toLowerCase(),cat=$('#filter').value;let found=experiments.filter(e=>(e.name+' '+e.category+' '+e.description).toLowerCase().includes(q)&&(cat==='all'||e.category===cat));$('#filtered-cards').innerHTML=found.length?found.map(card).join(''):'<p class="empty">No experiments match. Try another topic.</p>';};$('#search').oninput=filter;$('#filter').onchange=filter;filter();}
 if(view==='apparatus'){$('#dialog-body').innerHTML='<div class="apparatus-grid">'+[['⚗','Conical flask','Its narrow neck and broad base allow swirling while reducing splashes. Used for titration and gas reactions.'],['⌑','Beaker','A general vessel for mixing and heating. Its markings give approximate volumes.'],['↧','Burette','Delivers carefully measured volumes of liquid. Read the bottom of the meniscus at eye level.'],['⊥','Retort stand','Supports apparatus with clamps to keep an experiment stable.'],['♧','Thermometer','Measures temperature and helps reveal heating curves and phase changes.'],['±','Power supply','Provides controlled current for electrochemical reactions.']].map(([i,n,d])=>`<article class="apparatus-card"><span class="apparatus-icon">${i}</span><h3>${n}</h3><p>${d}</p></article>`).join('')+'</div><p class="science-note">Click labels or apparatus in the 3D scene to inspect their role in the current experiment.</p>';}
 if(view==='notebook')renderNotebook();
 if(view==='help'){$('#dialog-body').innerHTML=`<div class="help-copy"><h3>Learn by changing one thing.</h3><p>Choose an experiment, adjust a variable, and press Run. The 20-second animation compresses simulated time. Pause at any point to inspect the measurements. Record a result to keep your observations.</p><h3>Make the scene your own.</h3><p>Drag to orbit. Scroll or use + / − to zoom. Use the arrow buttons to rotate and ⌖ to reset the camera. Aa toggles labels. Select a label or an apparatus to learn about it.</p><h3>Free lab</h3><p>Switch between the six supported reaction models and add up to four decorative vessels to your bench. This release does not simulate arbitrary chemical combinations or transfers between extra vessels.</p><h3>Your work stays in this browser.</h3><p>Notebook entries and explored lessons are saved locally on this device. Export your notebook for a portable copy. There are no accounts, classroom management, or cloud sync in this version.</p><h3>Models, with clear boundaries.</h3><p>Calculations use simplified educational models. Each experiment’s Science tab states its assumptions. Particle sizes, reaction speed, apparatus scale, and liquid motion are illustrative. This is a learning simulation, not laboratory operating guidance.</p><h3>Built for curiosity.</h3><p>An original platform inspired by NOBOOK’s chemistry library and Learn Arduino’s interactive 3D teaching approach. All apparatus models in this site are generated from original geometry.</p></div>`;}
 if(!$('#drawer').open)$('#drawer').showModal();}
function renderNotebook(){ $('#dialog-body').innerHTML=`<div class="notes-form"><label for="note-text" class="eyebrow">WHAT DID YOU NOTICE?</label><textarea id="note-text" placeholder="Describe your observation or prediction…"></textarea><div style="display:flex;justify-content:space-between;gap:12px"><button id="save-note" class="primary-btn">Save observation with current result</button><button id="export-notes" class="outline-btn">Export notebook ↓</button></div></div><div id="notes-list">${notes.length?[...notes].reverse().map(n=>`<article class="note"><h3>${esc(n.title)}</h3><small>${esc(n.date)}</small><p>${esc(n.result)}</p>${n.text?'<p>'+esc(n.text)+'</p>':''}<footer><span>${esc(n.settings)}</span><button class="text-btn" data-delete-note="${esc(n.id)}">Remove</button></footer></article>`).join(''):'<div class="empty">Your next discovery belongs here.<br><br>Run an experiment and record the result, or write an observation above.</div>'}</div><p class="science-note">Saved on this browser only. Export to keep a backup.</p>`;$('#save-note').onclick=()=>{saveNote($('#note-text').value);renderNotebook();};$('#export-notes').onclick=exportNotes;document.querySelectorAll('[data-delete-note]').forEach(b=>b.onclick=()=>{let removed=notes.find(n=>n.id===b.dataset.deleteNote);notes=notes.filter(n=>n.id!==b.dataset.deleteNote);persist();cards();renderNotebook();toast('Entry removed.');if(removed){let undo=document.createElement('button');undo.textContent=' Undo';undo.style.color='#e5efc1';undo.onclick=()=>{notes.push(removed);persist();cards();renderNotebook();toast('Entry restored.');};$('#toast').append(undo);}});}
function saveNote(text=''){let r=simulate(current.id,params,progress);let n={id:crypto.randomUUID(),title:current.name,date:new Date().toLocaleString(),text:text.trim(),result:`${current.metricA}: ${r.a.toFixed(2)} ${current.unitA} · ${current.metricB}: ${r.b.toFixed(2)} ${current.unitB} · Progress: ${Math.round(progress*100)}%`,settings:current.controls.map(c=>`${c.label}: ${params[c.id]} ${c.unit}`).join(' · ')};notes.push(n);persist();cards();toast('Observation added to your notebook.');}
function exportNotes(){let md='# Chemia — Lab notebook\n\n'+notes.map(n=>`## ${n.title}\n${n.date}\n\n${n.result}\n\n${n.settings}\n\n${n.text}\n`).join('\n---\n\n');let url=URL.createObjectURL(new Blob([md],{type:'text/markdown'}));let a=document.createElement('a');a.href=url;a.download='chemia-notebook.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Notebook exported as Markdown.');}
$('#record').onclick=()=>saveNote();$('#open-notes').onclick=()=>openDialog('notebook');$('#free-lab').onclick=()=>{freeMode=true;activeTab='explore';select(current.id);toast('Free lab: explore six models and add vessels to your bench.');};$('#close-dialog').onclick=()=>$('#drawer').close();$('#drawer').addEventListener('close',()=>{document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view==='lab'));});$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer')){const r=$('#drawer').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#drawer').close();}});
document.addEventListener('click',e=>{let card=e.target.closest('[data-experiment]');if(card){freeMode=false;select(card.dataset.experiment);$('#drawer').close();return;}let nav=e.target.closest('[data-view]');if(nav){if(nav.dataset.view==='lab'){$('#drawer').close();document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b===nav));}else openDialog(nav.dataset.view);}});
$('#rotate-left').onclick=()=>{if(lab)lab.theta-=.25;};$('#rotate-right').onclick=()=>{if(lab)lab.theta+=.25;};$('#zoom-in').onclick=()=>{if(lab)lab.radius=Math.max(7,lab.radius-1);};$('#zoom-out').onclick=()=>{if(lab)lab.radius=Math.min(19,lab.radius+1);};$('#reset-camera').onclick=()=>lab?.resetCamera();$('#toggle-labels').onclick=()=>{let on=$('#toggle-labels').getAttribute('aria-pressed')!=='true';$('#toggle-labels').setAttribute('aria-pressed',on);$('#labels').hidden=!on;};window.addEventListener('hashchange',()=>select(location.hash.slice(1)));
try{lab=new LabScene($('#lab-canvas'),l=>{$('#object-info').hidden=false;$('#object-info').innerHTML=`<strong>${esc(l.name)}</strong><br>${esc(l.description)}<button aria-label="Close apparatus description">×</button>`;$('#object-info button').onclick=()=>$('#object-info').hidden=true;});}catch(error){console.error('3D initialization failed',error);$('#scene-fallback').hidden=false;$('#lab-canvas').hidden=true;}
select(location.hash.slice(1)||'titration');requestAnimationFrame(loop);
